//! PrototypeList - Interface prototype identifiers for Boa bindings
//!
//! This module provides the equivalent of SpiderMonkey's generated PrototypeList.rs
//! but implemented directly in Rust for the Boa JS engine.
//!
//! In SpiderMonkey, this is generated by codegen.py from WebIDL definitions.
//! For Boa, we define a static set of interface IDs and provide runtime registration.

use std::sync::atomic::{AtomicUsize, Ordering};

/// Maximum length of the prototype chain for any interface.
/// This matches SpiderMonkey's MAX_PROTO_CHAIN_LENGTH.
pub const MAX_PROTO_CHAIN_LENGTH: usize = 8;

/// Counter for dynamically assigned prototype IDs
static NEXT_PROTO_ID: AtomicUsize = AtomicUsize::new(0);

/// Counter for dynamically assigned constructor IDs
static NEXT_CONSTRUCTOR_ID: AtomicUsize = AtomicUsize::new(0);

/// Get the next available prototype ID
pub fn allocate_proto_id() -> usize {
    NEXT_PROTO_ID.fetch_add(1, Ordering::SeqCst)
}

/// Get the next available constructor ID
pub fn allocate_constructor_id() -> usize {
    NEXT_CONSTRUCTOR_ID.fetch_add(1, Ordering::SeqCst)
}

/// Get the current count of registered prototypes
pub fn proto_count() -> usize {
    NEXT_PROTO_ID.load(Ordering::SeqCst)
}

/// Get the current count of registered constructors
pub fn constructor_count() -> usize {
    NEXT_CONSTRUCTOR_ID.load(Ordering::SeqCst)
}

/// Total number of prototype and interface slots (dynamic)
pub fn proto_or_iface_length() -> usize {
    proto_count() + constructor_count()
}

/// Interface prototype identifier.
/// 
/// In SpiderMonkey, ID is an enum with variants for each WebIDL interface.
/// In Boa, we use a newtype wrapper around usize for dynamic registration.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(transparent)]
pub struct ID(pub u16);

impl ID {
    /// Special "Last" sentinel value indicating end of valid IDs
    pub const LAST: ID = ID(u16::MAX);
    
    /// Create a new prototype ID
    pub const fn new(value: u16) -> Self {
        ID(value)
    }
    
    /// Get the numeric value of this ID
    pub const fn as_u16(self) -> u16 {
        self.0
    }
    
    /// Check if this is the Last sentinel
    pub const fn is_last(self) -> bool {
        self.0 == u16::MAX
    }
}

impl From<u16> for ID {
    fn from(value: u16) -> Self {
        ID(value)
    }
}

impl From<ID> for u16 {
    fn from(id: ID) -> Self {
        id.0
    }
}

impl From<ID> for usize {
    fn from(id: ID) -> Self {
        id.0 as usize
    }
}

/// Constructor identifier for interfaces with constructors.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(transparent)]
pub struct Constructor(pub u16);

impl Constructor {
    /// Create a new constructor ID with offset from prototype IDs
    pub const fn new(value: u16) -> Self {
        Constructor(value)
    }
    
    /// Get the numeric value of this constructor ID
    pub const fn as_u16(self) -> u16 {
        self.0
    }
}

impl From<u16> for Constructor {
    fn from(value: u16) -> Self {
        Constructor(value)
    }
}

impl From<Constructor> for u16 {
    fn from(ctor: Constructor) -> Self {
        ctor.0
    }
}

impl From<Constructor> for usize {
    fn from(ctor: Constructor) -> Self {
        ctor.0 as usize
    }
}

