/// Register a new interface name for a prototype ID
pub fn register_interface_name(id: ID, name: &'static str) {
    let mut guard = INTERFACE_NAMES.write().unwrap();
    let names = guard.get_or_insert_with(init_interface_names);
    names.insert(id.0, name);
}

/// Get the interface name for a prototype ID.
/// Returns "Unknown" if the ID is not registered.
pub fn proto_id_to_name(proto_id: u16) -> &'static str {
    let guard = INTERFACE_NAMES.read().unwrap();
    if let Some(names) = guard.as_ref() {
        names.get(&proto_id).copied().unwrap_or("Unknown")
    } else {
        // Initialize lazily
        drop(guard);
        let mut write_guard = INTERFACE_NAMES.write().unwrap();
        let names = write_guard.get_or_insert_with(init_interface_names);
        names.get(&proto_id).copied().unwrap_or("Unknown")
    }
}

/// Interface chain for inheritance hierarchy.
/// 
/// Represents the prototype chain from most derived to base interface.
/// Padded with ID::LAST to MAX_PROTO_CHAIN_LENGTH.
#[derive(Debug, Clone, Copy)]
pub struct InterfaceChain {
    /// The chain of interface IDs, from most derived to base.
    /// Unused slots are filled with ID::LAST.
    pub chain: [ID; MAX_PROTO_CHAIN_LENGTH],
    /// The actual depth of the chain (number of valid IDs).
    pub depth: u8,
}

impl InterfaceChain {
    /// Create a new interface chain from a slice of IDs.
    /// The slice should be ordered from most derived to base.
    pub fn new(ids: &[ID]) -> Self {
        let mut chain = [ID::LAST; MAX_PROTO_CHAIN_LENGTH];
        let depth = ids.len().min(MAX_PROTO_CHAIN_LENGTH);
        
        for (i, &id) in ids.iter().take(depth).enumerate() {
            chain[i] = id;
        }
        
        InterfaceChain {
            chain,
            depth: depth as u8,
        }
    }
    
    /// Check if this interface chain contains the given ID.
    pub fn contains(&self, id: ID) -> bool {
        self.chain[..self.depth as usize].contains(&id)
    }
    
    /// Get the most derived interface ID.
    pub fn most_derived(&self) -> Option<ID> {
        if self.depth > 0 {
            Some(self.chain[0])
        } else {
            None
        }
    }
    
    /// Get the base interface ID.
    pub fn base(&self) -> Option<ID> {
        if self.depth > 0 {
            Some(self.chain[self.depth as usize - 1])
        } else {
            None
        }
    }
}

impl Default for InterfaceChain {
    fn default() -> Self {
        InterfaceChain {
            chain: [ID::LAST; MAX_PROTO_CHAIN_LENGTH],
            depth: 0,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    
    #[test]
    fn test_id_operations() {
        let id = ID::new(42);
        assert_eq!(id.as_u16(), 42);
        assert!(!id.is_last());
        assert!(ID::LAST.is_last());
    }
    
    #[test]
    fn test_constructor_id() {
        let ctor = Constructor::new(100);
        assert_eq!(ctor.as_u16(), 100);
    }
    
    #[test]
    fn test_interface_chain() {
        // HTMLDivElement -> HTMLElement -> Element -> Node -> EventTarget
        let chain = InterfaceChain::new(&[
            well_known::HTML_DIV_ELEMENT,
            well_known::HTML_ELEMENT,
            well_known::ELEMENT,
            well_known::NODE,
            well_known::EVENT_TARGET,
        ]);
        
        assert_eq!(chain.depth, 5);
        assert_eq!(chain.most_derived(), Some(well_known::HTML_DIV_ELEMENT));
        assert_eq!(chain.base(), Some(well_known::EVENT_TARGET));
        assert!(chain.contains(well_known::ELEMENT));
        assert!(!chain.contains(well_known::DOCUMENT));
    }
    
    #[test]
    fn test_proto_id_to_name() {
        assert_eq!(proto_id_to_name(well_known::NODE.0), "Node");
        assert_eq!(proto_id_to_name(well_known::ELEMENT.0), "Element");
        assert_eq!(proto_id_to_name(well_known::DOCUMENT.0), "Document");
    }
    
    #[test]
    fn test_dynamic_allocation() {
        let initial = proto_count();
        let id1 = allocate_proto_id();
        let id2 = allocate_proto_id();
        
        assert_eq!(id2, id1 + 1);
        assert_eq!(proto_count(), initial + 2);
    }
}
